pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // fund the contract with some Ether to exercise withdrawAll
        vm.deal(address(c), 1 ether);
    }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        // The owner must be the one triggering withdrawAll, as it is onlyOwner.
        // We let the fuzzer pick the owner address to show that withdrawAll works for any valid owner.
        vm.prank(owner);
        // The contract is already the owner because owner is set in constructor to msg.sender.
        // We need to ensure the caller is the owner; msg.sender in setUp is the test contract,
        // so we startPrank as the original deployer before setting up funding.
        // Actually, we just need to set the correct owner via a prank that matches the original deployer.
        // Let's redo: change owner to the fuzzed owner, then call withdrawAll.
        // But we cannot change owner. So we must use the fixed owner from setUp.
        // The invariant must hold for every owner? The original owner is fixed at construction.
        // The fuzzer should control scenario inputs. The difference is about balance changes.
        // The test should ensure withdrawAll can be called by the current owner and then check the balance.
        // We'll prank as the actual owner.
        vm.startPrank(c.owner());
        uint256 balanceBefore = address(c).balance;
        try c.withdrawAll() {
            // success: balance must be zero
            assertTrue(address(c).balance == 0);
        } catch {
            // if it reverts, the balance should not change
            assertTrue(address(c).balance == balanceBefore);
        }
        vm.stopPrank();
    }
}

