contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 sendAmount, uint256 withdrawAmount, address beneficiary, address nonOwner) public {
        vm.assume(sendAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(beneficiary != address(0) && beneficiary != address(c) && beneficiary != address(this));
        vm.assume(nonOwner != address(0) && nonOwner != address(c) && nonOwner != address(this) && nonOwner != beneficiary);
        vm.assume(nonOwner != c.owner());

        // Fund the contract with enough Ether for the sendAmount
