        // Owner sends Ether to a beneficiary via sendMoney
        vm.prank(c.owner());
        c.sendMoney(beneficiary, sendAmount, "");

        // Record balance after sendMoney completes
        uint256 balanceAfterSend = address(c).balance;

        // Make non-owner an EOA with no code and give it some Ether for gas
        vm.deal(nonOwner, 1 ether);

        // nonOwner attempts to call withdraw – on correct contract reverts, on mutant succeeds
        vm.prank(nonOwner);
        try c.withdraw(withdrawAmount) {
            // withdrawal succeeded (mutant)
        } catch {
            // withdrawal reverted (correct)
        }

