    constructor(C _c) { c = _c; }
    function test(address attacker, uint amount) public returns (bool) {
        require(attacker != c.owner());
        require(address(this).balance >= amount);
        bool reverted = false;
        (bool success, ) = address(this).call{value: amount}("");
        require(success);
        try c.sendMoney{value: amount}(attacker, 0, "") { } catch { reverted = true; }
