contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint amount, uint sendAmount) public payable {
        require(amount > 0);
        require(sendAmount > 0);
        require(address(this).balance >= sendAmount);
        bool revertedOwner;
        bool revertedNonOwner;
        try c.withdraw(amount) { revertedOwner = false; } catch { revertedOwner = true; }
        // Now test as non-owner: use call from this contract if it is not owner, else fail precondition.
        require(address(this) != caller);
        // We need to call withdraw as a different address. Since the only visible effect is revert, we can test with a send that changes owner.
        // Actually, we can't change sender arbitrarily without cheatcodes. Instead, we note that if caller is not owner, withdraw reverts.
        // The rule: if msg.sender (this contract) is not owner, withdraw(...) reverts. On P it doesn't revert for owner, but M reverts for owner if tx.origin != owner.
        // We test with a parameter that ensures tx.origin != address(this) by requiring the caller parameter is not the test contract address.
        // But msg.sender is always this contract's address here. So we precompute: the test contract is not owner -> withdraw reverts on P and M.
        // The difference is: on P, owner (this contract if set as owner) can always withdraw. On M, withdraw reverts even if msg.sender==owner but tx.origin!=owner.
        // So we need to check if this contract is owner, then withdraw should succeed on P but may fail on M if tx.origin differs.
        // We don't know tx.origin, so we set up: require the test contract is owner. Then P's withdraw doesn't revert. M's reverts if tx.origin != owner.
        // Since we can't guarantee tx.origin != owner in all contexts, we generalize: non-owner always reverts, owner never reverts (on P).
        // On M, owner may revert when tx.origin differs.
        // So we can assert: if this contract is owner, then !revertedOwner on P; on M it could be revertedOwner.
        // The test harness must have this contract be owner, which we can check via c.owner() == address(this).
        require(c.owner() == address(this)); // precondition for P's rule
        // On P, revertedOwner must be false (owner can withdraw).
        // On M, revertedOwner might be true because tx.origin != owner even though msg.sender == owner.
        assert(!revertedOwner);
    }
    receive() external payable {}
}

