pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = makeAddr("owner");

    function setUp() public {
        vm.prank(owner);
        c = new C();
        vm.deal(owner, 10 ether);
    }

    function testFuzz_property(address nonOwner, uint256 amount, bytes calldata data) public {
        // Keep amounts within balance
        bound(amount, 0, 10 ether);
        // nonOwner must differ from owner
        vm.assume(nonOwner != owner);
        // Ensure nonOwner has no code (EOA) — calls from it to Reverter will fail inside c's low-level call.
        // We need an adversarial counterparty that always reverts on call.
        Reverter revertee = new Reverter();

        // Precondition: nonOwner is not the owner but tx.origin will be owner via a nested call.
        // We achieve this by having the owner call a helper that pranks to nonOwner and calls c.sendMoney.
        // This makes msg.sender = nonOwner and tx.origin = owner.
        bool referenceOk;
        bool mutantOk;

        // Deploy a caller contract that will perform the pranked call.
        Caller caller = new Caller();
        vm.deal(address(caller), amount);
        // Reference contract call (should revert because msg.sender != owner)
        vm.prank(owner);
        try caller.callSendMoney(address(c), address(revertee), amount, data) {
            referenceOk = true;
        } catch {
            referenceOk = false;
        }

        // For the mutant, the same call should succeed because tx.origin == owner.
        // We verify on the actual contract c (the deployed reference) but the property must hold for reference.
        // Since we only have one C deployed (the reference), we assert that the reference always reverts in this scenario.
        // The mutant would allow this to succeed, thus distinguishing the bug.
        assertTrue(!referenceOk);
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter: always fails");
    }
}

contract Caller {
    function callSendMoney(address target, address reverter, uint256 amount, bytes calldata data) external payable {
        C(target).sendMoney{value: amount}(reverter, amount, data);
    }
}

